export const SURVEY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\" />\n<title>ForeAi — Course Survey</title>\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css\" />\n<style>\n  :root{ --bg:#0a1f14; --panel:#0e2a1c; --line:#1c4a33; --text:#eafff2; --faint:#9fc4b0; --accent:#39d98a; --tee:#ffffff; --gold:#e9c46a; }\n  *{ box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\n  html,body{ margin:0; height:100%; font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif; background:var(--bg); color:var(--text); }\n  #map{ position:fixed; inset:0; }\n  .bar{ position:fixed; left:8px; right:8px; z-index:1000; background:rgba(10,31,20,.92); border:1px solid var(--line); border-radius:14px; padding:8px 10px; backdrop-filter:blur(4px); }\n  #top{ top:8px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n  #bottom{ bottom:8px; display:flex; flex-direction:column; gap:8px; max-height:70vh; }\n  #tools{ display:flex; flex-direction:column; gap:8px; overflow-y:auto; }\n  #tools.hidden{ display:none; }\n  #toolsToggle{ padding:6px 10px; }\n  input,button,select{ font-size:16px; font-family:inherit; }\n  input[type=text]{ flex:1; min-width:120px; background:#07160e; color:var(--text); border:1px solid var(--line); border-radius:10px; padding:9px 11px; }\n  button{ background:#123c28; color:var(--text); border:1px solid var(--line); border-radius:10px; padding:9px 12px; font-weight:600; }\n  button:active{ transform:scale(.97); }\n  button.pri{ background:var(--accent); color:#04150c; border-color:var(--accent); }\n  button.on{ outline:2px solid var(--accent); }\n  .row{ display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n  .grow{ flex:1; }\n  .hole{ font-size:20px; font-weight:800; min-width:44px; text-align:center; }\n  .pt{ flex:1; padding:11px 6px; }\n  .prog{ color:var(--faint); font-size:13px; }\n  .prog b{ color:var(--text); }\n  .ok{ color:var(--accent); }\n  .no{ color:#e7795a; }\n  .hint{ color:var(--faint); font-size:12px; }\n  #msg{ color:var(--gold); font-size:12px; min-height:14px; }\n  .count{ background:#07160e; border:1px solid var(--line); border-radius:8px; padding:3px 8px; font-size:12px; color:var(--faint); }\n  /* Phones: shrink the controls so the map keeps most of the screen. */\n  @media (max-width:600px){\n    .bar{ left:6px; right:6px; padding:6px 8px; border-radius:12px; }\n    #bottom{ gap:6px; max-height:58vh; }\n    #tools{ gap:6px; }\n    .row{ gap:6px; }\n    button{ padding:8px 9px; font-size:13px; }\n    .pt{ padding:8px 3px; font-size:13px; }\n    input,select{ font-size:15px; }\n    input[type=text]{ padding:8px 9px; }\n    .hole{ font-size:17px; min-width:30px; }\n    .prog{ font-size:11px; }\n    .hint{ font-size:11px; line-height:1.35; }\n    #top{ gap:6px; }\n  }\n</style>\n</head>\n<body>\n<div id=\"map\"></div>\n\n<div id=\"top\" class=\"bar\">\n  <input id=\"course\" type=\"text\" placeholder=\"Course name (e.g. Kempton Park Golf Club)\" />\n  <input id=\"search\" type=\"text\" placeholder=\"Find a place / course\" />\n  <button onclick=\"doSearch()\">Go</button>\n</div>\n\n<div id=\"bottom\" class=\"bar\">\n  <div class=\"row\">\n    <button onclick=\"stepHole(-1)\">◀</button>\n    <div class=\"hole\" id=\"holeNum\">1</div>\n    <button onclick=\"stepHole(1)\">▶</button>\n    <div class=\"prog grow\" id=\"prog\"></div>\n    <button onclick=\"dropGPS()\" title=\"Drop the highlighted point at my current GPS location\">📍</button>\n    <button id=\"toolsToggle\" onclick=\"toggleTools()\" title=\"Show/hide tools\">▾</button>\n    <select id=\"holeCount\" onchange=\"setCount()\"><option value=\"18\">18 holes</option><option value=\"9\">9 holes</option></select>\n  </div>\n  <div id=\"tools\">\n  <div class=\"row\">\n    <button class=\"pt on\" data-t=\"tee\"   onclick=\"setType('tee')\">🏳️ Tee</button>\n    <select id=\"teeSel\" onchange=\"teeName=this.value; setType('tee');\" title=\"Which tee box (colour)\"><option>White</option><option>Blue</option><option>Red</option><option>Yellow</option><option>Green</option><option>Black</option><option>Gold</option></select>\n    <button class=\"pt\"     data-t=\"green\" onclick=\"setType('green')\">🟢 Green</button>\n    <button class=\"pt\"     data-t=\"greenFront\" onclick=\"setType('greenFront')\">Front</button>\n    <button class=\"pt\"     data-t=\"greenBack\"  onclick=\"setType('greenBack')\">Back</button>\n    <button class=\"pt\"     data-t=\"fairway\" onclick=\"setType('fairway')\">🛣️ Fairway</button>\n  </div>\n  <div class=\"row\">\n    <button class=\"pt\" data-t=\"tree\"   onclick=\"setType('tree')\">🌳 Trees</button>\n    <button class=\"pt\" data-t=\"water\"  onclick=\"setType('water')\">💧 Water</button>\n    <select id=\"waterMode\" onchange=\"waterMode=this.value; setType('water');\" title=\"River = brush a line · Pond = tap a loop\"><option value=\"river\">River (brush)</option><option value=\"pond\">Pond (tap loop)</option></select>\n    <button class=\"pt\" data-t=\"bunker\" onclick=\"setType('bunker')\">🏖️ Bunker</button>\n    <button onclick=\"finishShape()\">✓ Finish shape</button>\n    <span class=\"count\" id=\"hazCount\">0 hazards</span>\n  </div>\n  <div class=\"row\">\n    <button onclick=\"undo()\">Undo point</button>\n    <button onclick=\"clearHole()\">Clear hole</button>\n    <span class=\"count\" id=\"count\">0 / 18 holes done</span>\n  </div>\n  <div class=\"row\">\n    <input id=\"importFile\" type=\"file\" accept=\"application/json,.json\" style=\"display:none\" onchange=\"importFile(event)\" />\n    <button class=\"grow\" onclick=\"document.getElementById('importFile').click()\">⬆ Load a saved coords file</button>\n    <button class=\"pri grow\" onclick=\"download()\">⬇ Download coords</button>\n  </div>\n  <div id=\"msg\"></div>\n  <div class=\"hint\">You don't need to be at the course — this works from any computer on the satellite map. Tap to drop the highlighted point; <b>drag any dot</b> to nudge it into place. <b>🏳️ Tee</b> uses the colour picker beside it — place a tee by its real colour (Kempton Park is White, Red &amp; Blue), then change the colour to add another (great for school days with extra tee boxes). <b>🛣️ Fairway</b> drops ordered waypoints down the middle (tap the bends tee→green). <b>💧 Water</b> has two modes beside it: <b>River</b> = press and <b>drag</b> along the stream to trace its flow (draws as a flowing river); <b>Pond</b> = <b>tap</b> around the edge of a dam/lake and <b>✓ Finish shape</b> to fill it. <b>Trees / Bunker</b> tap around the edge; <b>✓ Finish shape</b> starts the next. <b>⬆ Load</b> reopens a coords file you saved earlier so you can keep editing anywhere. Tap <b>▾</b> to hide these tools and get the full map. Progress is also saved on this device.</div>\n  </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js\"></script>\n<script>\n  var LS='foreai.survey.v1';\n  var state = load() || { course:'', count:18, holes:{} }; // holes[n] = {tee,green,greenFront,greenBack}\n  var cur = 1, type = 'tee';\n  // Tee boxes: a hole can have several (club/men/ladies/junior + a spare). Stored\n  // per hole as h.tees = { name: {lat,lng} }; h.tee mirrors the back tee for the app.\n  // Tee boxes named by their real course colour (e.g. Kempton Park uses White,\n  // Red and Blue). Each marker draws in its tee colour. TEE_ORDER runs\n  // longest→shortest so the app treats the longest available tee as the \"back\"\n  // tee for hole length (Blue/Black are championship, Red is forward).\n  var TEE_COLORS = { White:'#f4f4f4', Blue:'#5aa0ff', Red:'#e8563e', Yellow:'#f2c94c', Green:'#39d98a', Black:'#20242b', Gold:'#e9c46a' };\n  var TEE_ORDER = ['Black','Blue','White','Gold','Yellow','Green','Red'];\n  var teeName = 'White';\n  var waterMode = 'river'; // 'river' = brush a flow line · 'pond' = tap a loop to fill\n  function backTee(h){ if(!h.tees) return undefined;\n    for(var i=0;i<TEE_ORDER.length;i++){ if(h.tees[TEE_ORDER[i]]) return h.tees[TEE_ORDER[i]]; }\n    for(var k in h.tees) return h.tees[k]; return undefined; }\n  var openHz = null; // hazard shape currently being drawn (points appended to it)\n\n  // ---- map (free Esri World Imagery, no key) ----\n  var map = L.map('map', { zoomControl:true, tap:true }).setView([-26.1016, 28.236], 16); // default: Kempton Park\n  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',\n    { maxZoom:21, maxNativeZoom:19, attribution:'Imagery © Esri' }).addTo(map);\n  // faint place/road labels on top so you can orient\n  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',\n    { maxZoom:21, maxNativeZoom:19, opacity:0.7 }).addTo(map);\n\n  var layer = L.layerGroup().addTo(map);\n  var COLORS = { tee:'#ffffff', green:'#39d98a', greenFront:'#e9c46a', greenBack:'#e76f51',\n                 tree:'#2f9e4f', water:'#3a86c8', bunker:'#e6d29a' };\n  function isHazard(t){ return t==='tree'||t==='water'||t==='bunker'; }\n\n  // A round dot icon for draggable markers (so points can be nudged from home).\n  function dotIcon(color, px){\n    return L.divIcon({ className:'dragdot',\n      html:'<div style=\"width:'+px+'px;height:'+px+'px;border-radius:50%;background:'+color+';border:2px solid #04150c;box-shadow:0 0 0 1.5px rgba(255,255,255,.55)\"></div>',\n      iconSize:[px,px], iconAnchor:[px/2,px/2] });\n  }\n  // Draggable point on the current hole. onMove(lat,lng) writes it back to state.\n  function dragDot(lat, lng, color, px, onMove, tip){\n    var m = L.marker([lat,lng], { icon:dotIcon(color,px), draggable:true, autoPan:true, keyboard:false }).addTo(layer);\n    if(tip) m.bindTooltip(tip,{permanent:false});\n    m.on('dragend', function(){ var ll=m.getLatLng(); onMove(round(ll.lat), round(ll.lng)); save(); redraw(); });\n    return m;\n  }\n\n  // Water has two modes: a River is a BRUSH (press-drag a flow line); a Pond is\n  // tapped like other areas (a loop that fills). Everything else drops on tap.\n  map.on('click', function(e){ if(type==='water' && waterMode==='river') return; place(e.latlng.lat, e.latlng.lng); });\n\n  var RIVER_WIDTH = 10; // metres, default river width\n  var brushing=false, brushHz=null, lastBrushLL=null;\n  var mapEl = map.getContainer();\n  function brushLL(e){ var r=mapEl.getBoundingClientRect(); return map.containerPointToLatLng(L.point(e.clientX-r.left, e.clientY-r.top)); }\n  function addBrush(ll){\n    if(lastBrushLL && map.distance(lastBrushLL, ll) < 3) return; // ~3 m spacing\n    lastBrushLL = ll; brushHz.points.push({ lat:round(ll.lat), lng:round(ll.lng) });\n    save(); redraw();\n  }\n  mapEl.addEventListener('pointerdown', function(e){\n    if(type!=='water' || waterMode!=='river') return;\n    brushing=true; lastBrushLL=null; map.dragging.disable(); mapEl.setPointerCapture&&mapEl.setPointerCapture(e.pointerId);\n    var h = state.holes[cur] || (state.holes[cur] = {});\n    brushHz = { type:'water', width:RIVER_WIDTH, points:[] };\n    (h.hazards || (h.hazards = [])).push(brushHz);\n    addBrush(brushLL(e)); e.preventDefault();\n  });\n  mapEl.addEventListener('pointermove', function(e){ if(brushing){ addBrush(brushLL(e)); e.preventDefault(); } });\n  function endBrush(){ if(!brushing) return; brushing=false; map.dragging.enable();\n    if(brushHz && brushHz.points.length<1){ var h=state.holes[cur]; if(h&&h.hazards) h.hazards.pop(); }\n    var n = brushHz?brushHz.points.length:0; brushHz=null; save(); redraw(); msg('River drawn · '+n+' pts (drag again for another)');\n  }\n  mapEl.addEventListener('pointerup', endBrush);\n  mapEl.addEventListener('pointercancel', endBrush);\n\n  function place(lat, lng){\n    var h = state.holes[cur] || (state.holes[cur] = {});\n    if (isHazard(type)) {\n      // A hazard is a shape: tap around the edge of a river / tree line / bunker\n      // and the taps join into one area. openHz is the shape currently being\n      // drawn; \"Finish shape\" closes it so the next taps start a new hazard.\n      var list = h.hazards || (h.hazards = []);\n      if (!openHz || openHz._hole !== cur || openHz.type !== type) {\n        openHz = { type:type, points:[], _hole:cur };\n        list.push(openHz);\n      }\n      openHz.points.push({ lat:round(lat), lng:round(lng) });\n      save(); redraw(); msg('Hole '+cur+' · '+label(type)+' shape · '+openHz.points.length+' pts');\n      return;\n    }\n    if (type==='fairway') {\n      // Ordered path down the fairway (tee → these → green). Tap the bends.\n      (h.fairway || (h.fairway = [])).push({ lat:round(lat), lng:round(lng) });\n      save(); redraw(); msg('Hole '+cur+' · fairway point '+h.fairway.length);\n      return;\n    }\n    if (type==='tee') {\n      // Each colour is one tee box; placing again moves that box. Pick another\n      // colour from the dropdown to add more (club/men/ladies/junior).\n      (h.tees || (h.tees = {}))[teeName] = { lat:round(lat), lng:round(lng) };\n      h.tee = backTee(h); // app uses the back tee for hole length + fairway start\n      save(); redraw(); msg('Hole '+cur+' · '+teeName+' tee set');\n      return;\n    }\n    h[type] = { lat:round(lat), lng:round(lng) };\n    save(); redraw(); msg('Hole '+cur+' · '+label(type)+' set');\n  }\n  function round(n){ return Math.round(n*1e6)/1e6; }\n\n  // ---- drop a point at my real GPS location (works in a browser and in the\n  //      survey APK's WebView, where location permission is granted natively) ----\n  var meMarker = null;\n  function dropGPS(){\n    if(!navigator.geolocation){ msg('GPS is not available on this device.'); return; }\n    msg('Locating…');\n    navigator.geolocation.getCurrentPosition(function(pos){\n      var la=round(pos.coords.latitude), ln=round(pos.coords.longitude);\n      var acc=pos.coords.accuracy?(' ±'+Math.round(pos.coords.accuracy)+'m'):'';\n      map.setView([la,ln], Math.max(map.getZoom(),18));\n      if(meMarker){ layer.removeLayer(meMarker); }\n      place(la, ln); // drops in the current mode (tee/green/hazard vertex…)\n      msg('Dropped '+label(type)+(type==='tee'?' ('+teeName+')':'')+' at your location'+acc);\n    }, function(err){\n      msg('Could not get GPS — '+((err&&err.message)||'is location permission on?'));\n    }, { enableHighAccuracy:true, timeout:15000, maximumAge:0 });\n  }\n\n  function redraw(){\n    layer.clearLayers();\n    Object.keys(state.holes).forEach(function(n){\n      var h = state.holes[n], isCur = (+n===cur);\n      // tee boxes (one coloured marker per tee) then green markers\n      Object.keys(h.tees||{}).forEach(function(name){\n        var p = h.tees[name], col = TEE_COLORS[name] || '#ffffff', tip = n+' '+name+' tee';\n        if(isCur){\n          dragDot(p.lat, p.lng, col, 16, function(la,ln){ h.tees[name]={lat:la,lng:ln}; h.tee=backTee(h); }, tip);\n        } else {\n          L.circleMarker([p.lat,p.lng], { radius:5, color:'#04150c', weight:1.5, fillColor:col, fillOpacity:0.55 }).addTo(layer).bindTooltip(tip,{permanent:false});\n        }\n      });\n      ['green','greenFront','greenBack'].forEach(function(t){\n        if(!h[t]) return;\n        var tip = n+(t==='green'?' green':t==='greenFront'?' F':' B');\n        if(isCur){\n          dragDot(h[t].lat, h[t].lng, COLORS[t], 18, function(la,ln){ h[t]={lat:la,lng:ln}; }, tip);\n        } else {\n          L.circleMarker([h[t].lat,h[t].lng], { radius:5, color:'#04150c', weight:1.5, fillColor:COLORS[t], fillOpacity:0.55 }).addTo(layer).bindTooltip(tip,{permanent:false});\n        }\n      });\n      // Playing route: tee → fairway waypoints → green (bends through the fairway).\n      // Falls back to a straight tee→green line when no fairway path is mapped.\n      if(h.tee && h.green){\n        var fw = h.fairway || [];\n        var route = [[h.tee.lat,h.tee.lng]].concat(fw.map(function(p){return [p.lat,p.lng];})).concat([[h.green.lat,h.green.lng]]);\n        L.polyline(route,\n          { color:isCur?'#39d98a':'#2b6b4a', weight:isCur?3:2, dashArray: fw.length?null:'6,5', opacity:isCur?0.95:0.5 }).addTo(layer);\n        fw.forEach(function(p, idx){\n          if(isCur){\n            dragDot(p.lat, p.lng, '#39d98a', 14, function(la,ln){ h.fairway[idx]={lat:la,lng:ln}; }, n+' fairway '+(idx+1));\n          } else {\n            L.circleMarker([p.lat,p.lng], { radius:3, color:'#04150c', weight:1, fillColor:'#39d98a', fillOpacity:0.5 }).addTo(layer);\n          }\n        });\n      }\n      // hazards: water = brushed river ribbon; trees/bunkers = tapped outlines.\n      (h.hazards||[]).forEach(function(hz){\n        var col = COLORS[hz.type]||'#fff';\n        var pts = (hz.points||[]).map(function(p){ return [p.lat,p.lng]; });\n        var open = (hz===openHz);\n        if(hz.type==='water' && hz.width){\n          // a river: a thick rounded blue line following the brushed path\n          if(pts.length>=2){\n            L.polyline(pts, { color:'#bfe4f5', weight:isCur?9:6, opacity:isCur?0.55:0.3, lineCap:'round', lineJoin:'round' }).addTo(layer);\n            L.polyline(pts, { color:'#3a86c8', weight:isCur?6:4, opacity:isCur?0.95:0.6, lineCap:'round', lineJoin:'round' }).addTo(layer).bindTooltip(n+' river',{permanent:false});\n          } else if(pts.length===1){\n            L.circleMarker(pts[0], { radius:isCur?6:4, color:'#04150c', weight:1, fillColor:'#3a86c8', fillOpacity:0.85 }).addTo(layer);\n          }\n          return; // no per-point dots for a river (too many to drag)\n        }\n        // pond water (no width) falls through to the filled-polygon branch below\n        if(pts.length>=3){\n          L.polygon(pts, { color:'#04150c', weight:isCur?1.5:1, fillColor:col,\n            fillOpacity:isCur?(open?0.55:0.4):0.25, dashArray:open?'4,3':null })\n            .addTo(layer).bindTooltip(n+' '+hz.type+' area',{permanent:false});\n        } else if(pts.length===2){\n          L.polyline(pts, { color:col, weight:isCur?3:2, opacity:isCur?0.9:0.5 }).addTo(layer);\n        }\n        // vertex dots so each tap is visible; draggable on the current hole.\n        pts.forEach(function(pt, j){\n          if(isCur){\n            dragDot(pt[0], pt[1], col, 13, function(la,ln){ hz.points[j]={lat:la,lng:ln}; }, n+' '+hz.type);\n          } else {\n            L.circleMarker(pt, { radius:3, color:'#04150c', weight:1, fillColor:col, fillOpacity:0.4 }).addTo(layer);\n          }\n        });\n      });\n    });\n    updateUI();\n  }\n\n  function updateUI(){\n    document.getElementById('holeNum').textContent = cur;\n    document.querySelectorAll('.pt').forEach(function(b){ b.classList.toggle('on', b.dataset.t===type); });\n    var h = state.holes[cur]||{};\n    function m(t){ return h[t] ? '<span class=\"ok\">✓</span>' : '<span class=\"no\">—</span>'; }\n    var fwN = (h.fairway||[]).length;\n    var fwm = fwN ? '<span class=\"ok\">✓'+fwN+'</span>' : '<span class=\"no\">—</span>';\n    document.getElementById('prog').innerHTML = 'Tee '+m('tee')+' · Green '+m('green')+' · F '+m('greenFront')+' · B '+m('greenBack')+' · 🛣️ '+fwm;\n    var done = 0, fwDone = 0;\n    for(var n=1;n<=state.count;n++){ var x=state.holes[n]; if(x&&x.tee&&x.green) done++; if(x&&x.fairway&&x.fairway.length) fwDone++; }\n    document.getElementById('count').textContent = done+' / '+state.count+' holes · 🛣️ '+fwDone+' routed';\n    var hz = (state.holes[cur]||{}).hazards || [];\n    var hc = document.getElementById('hazCount'); if(hc) hc.textContent = hz.length+' hazard'+(hz.length===1?'':'s')+' on hole '+cur+(openHz&&openHz._hole===cur?' · drawing…':'');\n    document.getElementById('course').value = state.course||'';\n    document.getElementById('holeCount').value = String(state.count);\n  }\n\n  function toggleTools(){\n    var t=document.getElementById('tools'), b=document.getElementById('toolsToggle');\n    var hide=!t.classList.contains('hidden'); t.classList.toggle('hidden', hide);\n    b.textContent = hide ? '▸' : '▾';\n    setTimeout(function(){ map.invalidateSize(); }, 60); // let the map reclaim the space\n  }\n  function setType(t){ if(t!==type) openHz=null; type=t; updateUI(); }\n  function stepHole(d){ openHz=null; cur = Math.min(state.count, Math.max(1, cur+d)); type='tee'; redraw(); }\n  function finishShape(){\n    if(openHz){ var n=openHz.points.length; openHz=null; redraw(); msg('Shape closed ('+n+' pts). Next tap starts a new hazard.'); }\n    else msg('Tap the map to start a hazard shape, then press Finish.');\n  }\n  function setCount(){ state.count = +document.getElementById('holeCount').value; if(cur>state.count)cur=state.count; save(); redraw(); }\n  function undo(){\n    var h=state.holes[cur]; if(!h) return;\n    if(type==='water' && waterMode==='river'){\n      // Rivers are brushed in one stroke — undo removes the whole last river.\n      if(h.hazards){ for(var wi=h.hazards.length-1;wi>=0;wi--){ if(h.hazards[wi].type==='water' && h.hazards[wi].width){ h.hazards.splice(wi,1); save(); redraw(); msg('Removed the last river on hole '+cur); break; } } }\n      return;\n    }\n    if(type==='water'){ // pond: peel back the last vertex of the open/last pond\n      var pond = openHz;\n      if(!pond && h.hazards){ for(var pi=h.hazards.length-1;pi>=0;pi--){ if(h.hazards[pi].type==='water' && !h.hazards[pi].width){ pond=h.hazards[pi]; break; } } }\n      if(pond && pond.points.length){ pond.points.pop(); if(!pond.points.length){ var pk=h.hazards.indexOf(pond); if(pk>=0)h.hazards.splice(pk,1); if(pond===openHz)openHz=null; } save(); redraw(); msg('Removed a point from the pond'); }\n      return;\n    }\n    if(isHazard(type)){\n      // Remove the last vertex of the shape being drawn (or the last shape of\n      // this type). When a shape runs out of points it's removed entirely.\n      var shape = openHz;\n      if(!shape && h.hazards){ for(var i=h.hazards.length-1;i>=0;i--){ if(h.hazards[i].type===type){ shape=h.hazards[i]; break; } } }\n      if(shape && shape.points.length){\n        shape.points.pop();\n        if(!shape.points.length){ var k=h.hazards.indexOf(shape); if(k>=0)h.hazards.splice(k,1); if(shape===openHz)openHz=null; }\n        save(); redraw(); msg('Removed a point from a '+label(type)+' shape');\n      }\n      return;\n    }\n    if(type==='fairway'){\n      if(h.fairway && h.fairway.length){ h.fairway.pop(); save(); redraw(); msg('Removed a fairway point on hole '+cur); }\n      return;\n    }\n    if(type==='tee'){\n      if(h.tees && h.tees[teeName]){ delete h.tees[teeName]; if(!Object.keys(h.tees).length) delete h.tees; h.tee=backTee(h); save(); redraw(); msg('Removed '+teeName+' tee on hole '+cur); }\n      return;\n    }\n    if(h[type]){ delete h[type]; save(); redraw(); msg('Removed '+label(type)+' on hole '+cur); }\n  }\n  function clearHole(){ if(confirm('Clear all points on hole '+cur+'?')){ delete state.holes[cur]; save(); redraw(); } }\n  function label(t){ return t==='tee'?'tee':t==='green'?'green':t==='greenFront'?'green front':t==='greenBack'?'green back':t==='tree'?'tree':t==='water'?'water':t==='bunker'?'bunker':t; }\n  function msg(s){ var m=document.getElementById('msg'); m.textContent=s; clearTimeout(msg._t); msg._t=setTimeout(function(){m.textContent='';},2500); }\n\n  document.getElementById('course').addEventListener('input', function(e){ state.course=e.target.value; save(); });\n\n  // ---- free geocoding via OpenStreetMap Nominatim (no key) ----\n  async function doSearch(){\n    var q=document.getElementById('search').value.trim(); if(!q) return;\n    msg('Searching…');\n    try{\n      var r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=za&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});\n      var j=await r.json();\n      if(j&&j[0]){ map.setView([+j[0].lat,+j[0].lon], 16); msg('Found: '+(j[0].display_name||q).split(',')[0]); }\n      else msg('No match — pan the map to the course manually.');\n    }catch(e){ msg('Search failed — pan to the course manually.'); }\n  }\n\n  // ---- export ----\n  function buildExport(){\n    var holes=[];\n    for(var n=1;n<=state.count;n++){\n      var h=state.holes[n]; if(!h) continue;\n      var o={ hole:n };\n      ['tee','green','greenFront','greenBack'].forEach(function(t){ if(h[t]) o[t]=h[t]; });\n      if(h.tees && Object.keys(h.tees).length){\n        o.tees = Object.keys(h.tees).map(function(name){ return { name:name, lat:h.tees[name].lat, lng:h.tees[name].lng }; });\n      }\n      if(h.fairway && h.fairway.length) o.fairway = h.fairway;\n      if(h.hazards && h.hazards.length){\n        o.hazards = h.hazards\n          .filter(function(hz){ return hz.points && hz.points.length; })\n          .map(function(hz){ return hz.type==='water' && hz.width ? { type:hz.type, width:hz.width, points:hz.points } : { type:hz.type, points:hz.points }; });\n      }\n      if(Object.keys(o).length>1) holes.push(o);\n    }\n    var data={ course: state.course||'(unnamed course)', capturedAt:new Date().toISOString(), holeCount:state.count, holes:holes };\n    var filename=(state.course||'course').replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'-coords.json';\n    return { data:data, holes:holes, filename:filename };\n  }\n  function download(){\n    var out = buildExport();\n    var json = JSON.stringify(out.data, null, 2);\n    // In the survey APK there's no file system to \"download\" to — hand the JSON\n    // to the native app, which opens the Share sheet (email / Drive / WhatsApp).\n    if (window.ReactNativeWebView && window.ReactNativeWebView.postMessage){\n      window.ReactNativeWebView.postMessage(JSON.stringify({ kind:'export', filename:out.filename, json:json }));\n      msg('Sharing '+out.holes.length+' holes…');\n      return;\n    }\n    var blob=new Blob([json],{type:'application/json'});\n    var a=document.createElement('a'); a.href=URL.createObjectURL(blob);\n    a.download=out.filename;\n    a.click();\n    msg('Downloaded '+out.holes.length+' holes');\n  }\n\n  // ---- import: reopen a saved coords file to keep editing from anywhere ----\n  function importFile(ev){\n    var f = ev.target.files && ev.target.files[0];\n    ev.target.value = ''; // allow re-importing the same file later\n    if(!f) return;\n    var r = new FileReader();\n    r.onload = function(){\n      var d; try{ d = JSON.parse(r.result); }catch(e){ msg('That file is not valid JSON.'); return; }\n      var holes = (d && d.holes) || [];\n      if(!Array.isArray(holes) || !holes.length){ msg('No holes found in that file.'); return; }\n      if(!confirm('Load '+holes.length+' holes from \"'+(d.course||f.name)+'\"? This replaces what is on screen.')) return;\n      var ns = { course: d.course||'', count: d.holeCount||state.count||18, holes:{} };\n      holes.forEach(function(o){\n        var n = o.hole; if(!n) return;\n        var hh = {};\n        ['tee','green','greenFront','greenBack'].forEach(function(t){ if(o[t]) hh[t]={lat:o[t].lat,lng:o[t].lng}; });\n        if(o.tees && o.tees.length){ hh.tees={}; o.tees.forEach(function(t){ hh.tees[t.name||'Club']={lat:t.lat,lng:t.lng}; }); if(!hh.tee) hh.tee=backTee(hh); }\n        if(o.fairway && o.fairway.length) hh.fairway = o.fairway.map(function(p){ return {lat:p.lat,lng:p.lng}; });\n        if(o.hazards && o.hazards.length){\n          hh.hazards = o.hazards.map(function(hz){\n            // Accept both the shape format {type,points:[...]} and the old point\n            // format {type,lat,lng} so any earlier export still loads.\n            if(hz.points){ var out={ type:hz.type, points:hz.points.map(function(p){ return {lat:p.lat,lng:p.lng}; }) }; if(hz.width) out.width=hz.width; return out; }\n            return { type:hz.type, points:[{lat:hz.lat,lng:hz.lng}] };\n          });\n        }\n        ns.holes[n] = hh;\n      });\n      state = ns; cur = 1; type = 'tee'; openHz = null;\n      save();\n      var first = ns.holes[1] || ns.holes[Object.keys(ns.holes)[0]];\n      var c = first && (first.tee || first.green);\n      if(c) map.setView([c.lat, c.lng], 17);\n      redraw();\n      msg('Loaded '+holes.length+' holes — drag any dot to adjust.');\n    };\n    r.readAsText(f);\n  }\n\n  function save(){ try{ localStorage.setItem(LS, JSON.stringify(state)); }catch(e){} }\n  function load(){\n    try{\n      var s = JSON.parse(localStorage.getItem(LS));\n      if(s && s.holes){\n        // Migrate old point-hazards {type,lat,lng} to shapes {type,points:[...]}.\n        Object.keys(s.holes).forEach(function(n){\n          var hz = s.holes[n].hazards;\n          if(hz && hz.length && hz[0] && hz[0].lat!==undefined){\n            s.holes[n].hazards = hz.map(function(p){ return { type:p.type, points:[{ lat:p.lat, lng:p.lng }] }; });\n          }\n        });\n      }\n      return s;\n    }catch(e){ return null; }\n  }\n\n  redraw();\n</script>\n</body>\n</html>\n";
